trait EncodeAsStr {
    fn encode_as_str(&self) -> String;
}

impl<T: SolError> EncodeAsStr for T {
    fn encode_as_str(&self) -> String {
        let expected_error = self.abi_encode();
        String::from_utf8_lossy(&expected_error).to_string()
    }
}

