        to: Address,
        token_ids: Vec<U256>,
        amounts: Vec<U256>,
        data: Bytes,
    ) -> Result<(), Vec<u8>> {
        self.ownable.only_owner()?;
        self.erc1155
            ._mint_batch(to, token_ids, amounts, &data)
            .map_err(Into::into)
    }
